            if (shrunk) {
                if (old_cap > target_cap) {
                    freed_bytes += (size_t)(old_cap - target_cap) * sizeof(Row);
                }
                tbl->rows = shrunk;
                tbl->storage->rows = shrunk;
                tbl->storage->capacity = target_cap;
                tbl->capacity = target_cap;
            }
