    output = BIO_new(BIO_s_mem());
    ok = ok && output &&
         X509_NAME_print_ex(output, X509_get_issuer_name(certificate), 0,
                            XN_FLAG_RFC2253) >= 0 &&
         print_bio_value("Issuer", output);
