    destroy_database(g_committed); g_committed = NULL;
    clear_all_savepoints();
    undo_log_clear();
    release_database_file_lock();
    shutdown_snapshot_io();
    g_readonly = false;
    g_path[0] = '\0';
    g_backup_dir[0] = '\0';
    g_backup_interval = 0;
    g_pending = false;
    g_generation = 0;
